#include <pybind11/pybind11.h>
#include <torch/extension.h>
#include "acl/acl.h"
#include "torch_npu/csrc/core/npu/NPUStream.h"
#include "bmm_tiling.h"
extern "C" void bmm_do_fp16(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*,uint8_t*);
namespace bmm_ext {
using LF=void(*)(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*,uint8_t*);
pybind11::tuple run_batch_mat_mul_v3(const at::Tensor &a, const at::Tensor &b) {
    TORCH_CHECK(a.dim()==3&&b.dim()==3,"[B,M,K] and [B,K,N]");
    TORCH_CHECK(a.scalar_type()==at::kHalf,"fp16 only");
    TORCH_CHECK(a.sizes()[0]==b.sizes()[0]&&a.sizes()[2]==b.sizes()[1],"shape mismatch");
    TORCH_CHECK(a.is_contiguous()&&b.is_contiguous(),"contiguous");
    const auto B=a.sizes()[0], M=a.sizes()[1], K=a.sizes()[2], N=b.sizes()[2];
    const auto M_total=static_cast<int32_t>(B*M);
    const int32_t mNum=(M_total+DEFAULT_BLOCK_M-1)/DEFAULT_BLOCK_M;
    const int32_t uc=std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,mNum);
    const int32_t tpc=(mNum+uc-1)/uc;
    at::Tensor c=at::empty({B,M,N},a.options());
    at::Tensor tc=at::empty({sizeof(BmmKernelTiling)},at::device(at::kCPU).dtype(at::kByte));
    auto *t=reinterpret_cast<BmmKernelTiling*>(tc.data_ptr());
    t->M=static_cast<int32_t>(M); t->K=static_cast<int32_t>(K); t->N=static_cast<int32_t>(N);
    t->M_total=M_total; t->blockM=DEFAULT_BLOCK_M; t->usedCoreNum=uc; t->tasksPerCore=tpc;
    auto tn=tc.to(at::kPrivateUse1); auto stm=c10_npu::getCurrentNPUStream().stream(false);
    bmm_do_fp16(uc,stm,
        static_cast<uint8_t*>(const_cast<void*>(a.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(b.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(c.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(tn.storage().data())));
    return pybind11::make_tuple(c);
}}
PYBIND11_MODULE(_bmm_ext, m) { m.def("run_batch_mat_mul_v3",&bmm_ext::run_batch_mat_mul_v3,""); }

