#include "bmm_kernel.h"
extern "C" __global__ __aicore__ void bmm_custom_fp16(GM_ADDR a,GM_ADDR b,GM_ADDR c,GM_ADDR t){
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2); AscendC::TPipe p;
    BmmKernel<half> k; k.Init(a,b,c,t,&p); k.Process();
}
extern "C" void bmm_do_fp16(uint32_t d,void* s,uint8_t* a,uint8_t* b,uint8_t* c,uint8_t* t){
    bmm_custom_fp16<<<d,nullptr,s>>>(a,b,c,t);
}

